const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-gpu', '--font-render-hinting=none'],
    defaultViewport: null
  });

  const page = await browser.newPage();

  // A1 portrait at 150 DPI = 3508 x 4961 pixels
  // Use a reasonable scale for rendering
  const width = 594;   // mm at 1px/mm base
  const height = 841;  // mm at 1px/mm base
  const scale = 4;     // 4x for high-res output

  await page.setViewport({
    width: width,
    height: height,
    deviceScaleFactor: scale
  });

  const htmlPath = path.resolve('/app/global-internet-usage-infographic.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(htmlContent, {
    waitUntil: 'networkidle0',
    timeout: 60000
  });

  // Wait for all infographic containers to have canvas or svg children
  await page.waitForFunction(() => {
    const containers = document.querySelectorAll('.infographic-container');
    if (containers.length === 0) return false;
    return Array.from(containers).every(c => c.children.length > 0);
  }, { timeout: 30000 });

  // Extra wait for rendering
  await new Promise(r => setTimeout(r, 3000));

  const poster = await page.$('#poster');
  const box = await poster.boundingBox();

  await poster.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png'
  });

  console.log('Screenshot saved to /app/output/final_poster.png');
  console.log('Dimensions:', box.width * scale, 'x', box.height * scale);

  await browser.close();
})();
EOF
